/**
 * The club photo album, as used on the site.
 *
 * Photos 35 and above are used, plus photo 26 — requested by the club for the
 * Development Squad card and the same 1920x1080 as the rest. The other photos
 * in 1–34 are older, scanned or low-res, and several have text baked into the
 * image. Derivatives are generated by `scripts/optimise-photos.mjs` into
 * /public/photos.
 *
 * `focal` is the point crops are centred on, as a 0–1 fraction of the image.
 * It stops square and banner crops cutting heads off. Default is dead centre.
 *
 * Alt text describes what is happening. No child is named, and no caption
 * identifies an individual — see the consent note in README.md.
 */
export type PhotoTag =
  | 'ribbon-day'
  | 'club-night'
  | 'get-set-go'
  | 'jumps'
  | 'throws'
  | 'running'
  | 'volunteers'
  | 'team'
  | 'collage'

export interface Photo {
  id: number
  alt: string
  /** 0–1 fraction; { x: 0.5, y: 0.35 } biases the crop upward toward faces. */
  focal: { x: number; y: number }
  tags: PhotoTag[]
  /** True where a baked-in caption band was cropped off the bottom. */
  cropped?: boolean
  /** Two photos joined side by side — fine in the gallery, poor as a card. */
  diptych?: boolean
}

