const byId = new Map(photos.map((p) => [p.id, p]))

export function photo(id: number): Photo {
  const p = byId.get(id)
  if (!p) throw new Error(`Unknown photo id ${id} — add it to src/data/photos.ts`)
  return p
}

export function photosTagged(tag: PhotoTag): Photo[] {
  return photos.filter((p) => p.tags.includes(tag))
}

/** Photos suitable as a single hero or card image (not joined or collaged). */
export function singleFrame(list: Photo[] = photos): Photo[] {
  return list.filter((p) => !p.diptych)
}

export const consentNote =
  'Photos are used with the club’s photo consent. Email taupoathletics@gmail.com to request a photo be removed.'
